function s(v) { return String(v == null ? '' : v).trim(); }
const st = $input.all().map(function (i) { return i.json; });
const SIX = ['nexcore', 'recex', 'washtro', 'formverse', 'pixelence', 'doffair'];

// exactly the parser used in RW-2, so I can see which branch fails
function toCr(txt) {
  const t = s(txt).replace(/,/g, '');
  if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i);
  if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i);
  if (m) { return parseFloat(m[1]) / 100; }
  return null;
}

const headers = Object.keys(st[0] || {});
const six = [];
const allNull = [];
for (const r of st) {
  const n = s(r.startup);
  if (!n) { continue; }
  const raw = r.raise_inr_cr;
  const parsed = toCr(raw);
  const rec = { startup: n, active: s(r.active), raw_value: raw,
    raw_type: typeof raw, raw_json: JSON.stringify(raw), parsed: parsed };
  if (SIX.indexOf(n.toLowerCase().replace(/[^a-z0-9]/g, '')) >= 0) { six.push(rec); }
  if (parsed === null && s(r.active).toLowerCase() === 'yes') { allNull.push(rec); }
}
return [{ json: { headers: headers, the_six: six,
  every_active_startup_that_failed_to_parse: allNull,
  fail_count: allNull.length } }];
